INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (190801, "ミッションをクリアすると、\n報酬がもらえますよ！\n頑張ってください", "2030/01/01 14:59:59", 3.414, 2, 1, "2025/01/31 12:00:00", "カリン", 0.0, -416.5, 1, 62, 1, 1000001);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (190801, "ミッションをクリアして、\n報酬をゲットしましょう！", "2030/01/01 14:59:59", 3.099, 2, 2, "2025/01/31 12:00:00", "カリン", 0.0, -416.5, 1, 62, 1, 1000002);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (190801, "受け取ることができる\n報酬があるようです\n確認してみてください", "2030/01/01 14:59:59", 2.801, 2, 3, "2025/01/31 12:00:00", "カリン", 0.0, -416.5, 1, 63, 1, 1000003);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (190801, "報酬がもらえますよ！\nチェックしてみてください", "2030/01/01 14:59:59", 0.0, 2, 4, "2025/01/31 12:00:00", "カリン", 0.0, -416.5, 2, 63, 1, 1000004);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (190801, "ギルド管理協会です！\nイベント報酬券をお持ちでしたら、様々なアイテムと交換できますよ", "2030/01/01 14:59:59", 2.12, 1, 5, "2025/01/31 12:00:00", "カリン", 0.0, -363.0, 2, 64, 1, 1000005);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (190801, "お疲れさまです！\nこちらでイベント報酬券とアイテムを交換することができますよ", "2030/01/01 14:59:59", 1.68, 2, 6, "2025/01/31 12:00:00", "カリン", 0.0, -363.0, 1, 64, 1, 1000006);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (190801, "いつもありがとうございます！\n報酬交換ですか？\nでは、イベント報酬券とお引き換えいたしますね", "2030/01/01 14:59:59", 2.33, 1, 7, "2025/01/31 12:00:00", "カリン", 0.0, -363.0, 2, 64, 1, 1000007);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (133701, "今度の敵は、アタシにとっても\n放ってはおけない存在だ\n少年、アタシも全力で行くからさ\n一緒に守ろう、この世界を", "2030/01/01 14:59:59", 5.18, 7, 101, "2025/01/31 12:00:00", "ラビリスタ", -6.0, -285.0, 3, 61, 10201, 1020101);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (133901, "退屈の吹き飛ぶような\n戦いの気配がするなぁ坊や\nさっさとワタシをそこへ連れてゆけ\n世界も守ってやるさ、ついでにな", "2030/01/01 14:59:59", 8.77, 2, 201, "2025/01/31 12:00:00", "クリスティーナ", -2.0, -285.0, 1, 61, 10201, 1020102);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (133801, "おや、私の力が必要……と？\nグレゴールが手伝うそうですよ\n私は戦わないのか、という顔ですね\n……考えておきます", "2030/01/01 14:59:59", 15.5, 1, 301, "2025/01/31 12:00:00", "ネネカ", 0.0, -285.0, 6, 61, 10201, 1020103);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (134301, "わたしだけの歌…\n一緒に、探してくれる…？\nあなたがいれば…\nもっとがんばれるから…", "2030/01/01 14:59:59", 9.061, 5, 101, "2025/02/28 12:00:00", "ランファ", 0.0, -285.0, 2, 61, 10202, 1020201);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (134401, "同じ唱喚士として、仲間として\n私にできることをします\n…これも、あなたが\n背中を押してくれたおかげですよ", "2030/01/01 14:59:59", 7.699, 2, 201, "2025/02/28 12:00:00", "チカ", 0.0, -285.0, 1, 61, 10202, 1020202);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (134601, "世界の平和が私とクローチェさんに\nかかってるんですよね？\nぼっちには過大すぎる期待ですけど\nふ、二人でなら背負ってみせます！", "2030/01/01 14:59:59", 8.595, 2, 101, "2025/03/31 12:00:00", "アオイ", 0.0, -285.0, 1, 61, 10203, 1020301);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (134501, "新しく手に入れたこの翼で…\nナイトさんがどこにいたって\nわたし、駆けつけちゃいますよっ！\nクローチェ・エアリアル発進ですっ", "2030/01/01 14:59:59", 7.758, 2, 201, "2025/03/31 12:00:00", "クローチェ", 0.0, -285.0, 1, 61, 10203, 1020302);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (132302, "今日はダーリンとの初デート♪\n二人でショッピングして、その後は\n…って私、指名手配されてる！？\nちょ、た…助けてダーリン～！！", "2030/01/01 14:59:59", 7.0, 6, 101, "2025/04/30 12:00:00", "ルイズマリー", 0.0, -285.0, 2, 61, 10204, 1020401);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (132402, "ルイちゃんのおばあちゃん優しくて\nいつもにこにこで、イロハ大好き♪\nでも一番好きなのは、角がすっごく\n大きくてかっこいいとこなんだ～♪", "2030/01/01 14:59:59", 7.904, 2, 201, "2025/04/30 12:00:00", "イロハ", 0.0, -285.0, 1, 61, 10204, 1020402);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (132502, "ノゾミちゃんのおかげで売上が安定\nしてきたのに、臨時休業、痛すぎる\n…ま、ルイちゃんのために\n一肌脱ぐか。行くよイロハ～", "2030/01/01 14:59:59", 8.487, 2, 301, "2025/04/30 12:00:00", "ソノ", 0.0, -285.0, 4, 61, 10204, 1020403);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (134901, "ヲ～ッホッホ♪\nあたくし様と同じお空気を吸える\nお幸運を噛みしめなさいですわ～♪\nヲ～ッホッホッホ～♪", "2030/01/01 14:59:59", 8.763, 2, 101, "2025/05/31 12:00:00", "カノン", 0.0, -285.0, 1, 61, 10205, 1020502);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (134801, "いきますよ騎士さん！\nカノンさんと力を合わせて…力を…\n…本当にあの人なんなんです？\nこれまでになく不安なんですけど！", "2030/01/01 14:59:59", 6.417, 3, 201, "2025/05/31 12:00:00", "ツムギ", 0.0, -285.0, 1, 61, 10205, 1020503);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (135001, "『願いが叶う海岸』か…怪しい\nだというのに、阿賀斗紫布菜たちは\n呑気に戯れている…見ていられない\n騎士クンは、わたしが守ってみせる", "2030/01/01 14:59:59", 10.335, 7, 101, "2025/06/30 12:00:00", "エリス", 0.0, -285.0, 3, 61, 10206, 1020601);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (135101, "せっかくの夏休みなんだし\nたまにはビーチでゆっくりしましょ\n…え、もしかしてこの夏もあんまり\n休めなかったりする感じなの？", "2030/01/01 14:59:59", 6.281, 4, 201, "2025/06/30 12:00:00", "シェフィ", 0.0, -285.0, 2, 61, 10206, 1020602);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (135201, "いっぱい。たべて\nおおきく。なると\nせーぎ。まもれる。はず\nお兄。いっしょに。スイカ。たべよ", "2030/01/01 14:59:59", 12.244, 2, 301, "2025/06/30 12:00:00", "プレシア", 0.0, -285.0, 1, 61, 10206, 1020603);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (135301, "ひと夏の冒険のはじまりです！\nアネモネさんも楽しんでくれたら\n…できれば、もう少し\n仲良くなれたらうれしいな…", "2030/01/01 14:59:59", 6.339, 8, 101, "2025/07/31 12:00:00", "クリア", 0.0, -285.0, 2, 61, 10207, 1020701);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (135401, "─幻の花…\n本当にあるのか謎─ですけど\n探すくらいは、\n付き合ってもいいです", "2030/01/01 14:59:59", 8.184, 9, 201, "2025/07/31 12:00:00", "アネモネ", 0.0, -285.0, 7, 61, 10207, 1020702);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (129101, "あははっ！　笑う門には福来る！\n笑ってればきっと、複製世界にも\n未来はやってくるって信じてる！\nそうだよね、シナツちゃん！", "2030/01/01 14:59:59", 3.906, 2, 101, "2025/08/31 12:00:00", "アイラ", 0.0, -285.0, 9, 61, 10208, 1020801);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (129201, "繰り返されるリセットの先の未来\n何度願っても手に入らなかった未来\n…でも、私は諦めない。絶対にだ\nキミも同じだろ…アイラ？", "2030/01/01 14:59:59", 14.465, 2, 201, "2025/08/31 12:00:00", "シナツ", 0.0, -285.0, 1, 61, 10208, 1020802);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (100101, "アイラの世界のみんなも、\n一生懸命生きてるんだ…！\n…なのに、世界の危機だなんて！\nあたし、絶対、絶対力になるよ！", "2030/01/01 14:59:59", 8.662, 3, 301, "2025/08/31 12:00:00", "ヒヨリ", 0.0, -285.0, 4, 61, 10208, 1020803);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (100301, "シナツ…もう一人の私\n彼女が大切にしている世界を\n絶対に終わらせはしない…！\n彼女と笑い合える未来のために！", "2030/01/01 14:59:59", 10.915, 3, 401, "2025/08/31 12:00:00", "レイ", 0.0, -285.0, 1, 61, 10208, 1020804);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (135802, "あ、ど、ども…\nあ、あんま見ねぇでくれっと\nその、恥ずかしくて…\n体が熱くなって、溶けちまう…", "2030/01/01 14:59:59", 6.042, 7, 101, "2025/09/30 12:00:00", "ユキノ", 0.0, -285.0, 1, 61, 10209, 1020901);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (135903, "なんで俺が幽霊に…意味不明だ\nこれじゃ死んでも死にきれねェ\n悪ィがこれも何かの縁だ、\nよろしく頼むぜ騎士公", "2030/01/01 14:59:59", 9.402, 1, 201, "2025/09/30 12:00:00", "サツキ", 0.0, -285.0, 4, 61, 10209, 1020902);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (136902, "う、うじゅる…\nサツキ姉しゃまを助けるためにも\nまずは、腹ごしらえでしゅね…！\nタコ焼き、召し上がってくだしゃい", "2030/01/01 14:59:59", 8.16, 1, 301, "2025/09/30 12:00:00", "ルルィ", 0.0, -285.0, 8, 61, 10209, 1020903);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (137401, "ひさしぶりのジオ・ゲヘナ\n歓迎パーティーで起きた殺人事件！\nランドソルの名探偵の名にかけて\n解き明かしてみせようじゃないか！", "2030/01/01 14:59:59", 5.0, 2, 101, "2025/10/31 12:00:00", "カスミ", 0.0, -285.0, 3, 61, 10210, 1021001);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (136001, "…わたしはどこの誰なのでしょう\nどこから来てどこへ行くのでしょう\nこの事件の真相が分かれば、\n何かが掴めるような気がいたします", "2030/01/01 14:59:59", 8.12, 1, 201, "2025/10/31 12:00:00", "アラクネ", 0.0, -285.0, 4, 61, 10210, 1021002);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (136202, "ナーナ、すいりとかろんぱとか、\nむずかしくてわかんないけど…\nお友だちとドーナツのためならっ\nせーいっぱいがんばるよっ！", "2030/01/01 14:59:59", 6.386, 2, 301, "2025/10/31 12:00:00", "ナーナ", 0.0, -285.0, 4, 61, 10210, 1021003);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (136402, "騎士クンに想いを伝えたい…だから\nミソラちゃん、わたしがんばるね！\n…あれ？　わたし、なんでこんなに\n必死になってるんだろう…？", "2030/01/01 14:59:59", 7.438, 4, 101, "2025/11/30 12:00:00", "ユイ", 0.0, -285.0, 3, 61, 10211, 1021101);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (136302, "騎士さんとのデートはわたしに\nお任せです★　なのでユイさんは\n安心して計画に専念して…たくさん\nドキドキしちゃってくださいね", "2030/01/01 14:59:59", 8.35, 5, 201, "2025/11/30 12:00:00", "ミソラ", 0.0, -285.0, 1, 61, 10211, 1021102);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (136501, "新しい年がやってくるね！\nお正月の料理も飾りつけも、\nお姉ちゃんにお任せだよ♪\nみんなで楽しく新年を迎えよう！", "2030/01/01 14:59:59", 5.0, 2, 101, "2025/12/31 12:00:00", "シズル", 0.0, -285.0, 1, 61, 10212, 1021201);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (137902, "おうちの掃除もトラブルも、 \n世界を揺るがす大ピンチも！\n今年のことは今年のうちに \nサッサと片付けちゃいますっ！", "2030/01/01 14:59:59", 5.25, 2, 201, "2025/12/31 12:00:00", "リノ", 0.0, -285.0, 1, 61, 10212, 1021202);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (106801, "年の瀬はギルドマスターも\nつい駆け回っちゃう忙しい時期だ！\n一年いろいろあったけど\nお互いイイ年を迎えよう、少年！", "2030/01/01 14:59:59", 7.5, 2, 301, "2025/12/31 12:00:00", "ラビリスタ", 0.0, -285.0, 1, 61, 10212, 1021203);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (126501, "漂う異国の料理の香り…それだけで\n世界中を旅した気分に浸れますね\nふふ、ほらクローチェ\nあまりはしゃぎすぎないように…♪", "2030/01/01 14:59:59", 8.204, 2, 101, "2026/01/31 12:00:00", "ライラエル", 0.0, -285.0, 1, 61, 10213, 1021301);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (129701, "異界の姫君と煮炊きにて競い合う…\n感奮興起、いとをかし\n華やかなる祭典と相成るよう、一肌\n脱がせていただきとう存じまする", "2030/01/01 14:59:59", 7.176, 2, 201, "2026/01/31 12:00:00", "ネフィ＝ネラ", 0.0, -285.0, 1, 61, 10213, 1021302);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (133101, "『ビストロプリンセス』のために\n料理の特訓を重ねてまいりました\nこの料理で騎士様の…い、いえ\n皆様の心とお腹を満たしますわ！", "2030/01/01 14:59:59", 8.602, 5, 301, "2026/01/31 12:00:00", "ヴァイオレット", 0.0, -285.0, 1, 61, 10213, 1021303);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (138101, "多様な味わいが織りなすハーモニー\nそれこそが我が国の矜持です\nもしもそれを乱すようであれば\nわたしも優しくはありませんよ？", "2030/01/01 14:59:59", 10.14, 3, 102, "2026/02/06 12:00:00", "ライラエル", 0.0, -285.0, 1, 61, 10213, 1021304);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (138201, "煉獄の穢土にてひと際輝く民草の心\n此れを守護りまするがわっちの責務\n如何な困難待ち受けようと\n不退転の矜持に揺らぎはありんせん", "2030/01/01 14:59:59", 10.152, 7, 202, "2026/02/06 12:00:00", "ネフィ＝ネラ", 0.0, -285.0, 1, 61, 10213, 1021305);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (138001, "裏世界の皆様は危機を脱し、\n残るはランドソルの皆様のみ…\n彼らを救い出すために、どうか…\nお立ち下さいペコリーヌ姫…！", "2030/01/01 14:59:59", 9.688, 3, 302, "2026/02/06 12:00:00", "ヴァイオレット", 0.0, -285.0, 4, 61, 10213, 1021306);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (138301, "みなさん、お待たせしちゃいました\nペコリーヌ、完全復活です☆\nみなさんの食卓を守るため\nもう二度と、わたしはめげません！", "2030/01/01 14:59:59", 5.928, 1, 401, "2026/02/12 12:00:00", "ペコリーヌ", 0.0, -285.0, 2, 61, 10213, 1021307);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (138702, "成行きで参加することになっちゃっ\nた尻相撲大会。ううっ、恥ずかしい\nけどやるしかないよね。…騎士さん\nいっぱい応援してくださいね？", "2030/01/01 14:59:59", 9.19, 2, 101, "2026/02/28 12:00:00", "ワカナ", 0.0, -285.0, 4, 61, 10214, 1021401);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (138802, "「お姉ちゃんを守れる自分になる」\nあの日の約束、今こそ果たしてみせ\nます。例えお姉ちゃんに背くことに\nなっても。例えそれが尻相撲でも！", "2030/01/01 14:59:59", 8.724, 3, 201, "2026/02/28 12:00:00", "シオリ", 0.0, -285.0, 1, 61, 10214, 1021402);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (138902, "私がへんたいふしんしゃさんって…\nただ生きているだけなのに、ひどい\n…まぁ死んでるんですけど…とか\n言ってる暇もない感じですか？", "2030/01/01 14:59:59", 7.758, 1, 101, "2026/03/31 12:00:00", "グレイス", 0.0, -285.0, 4, 61, 10215, 1021501);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (139002, "あの、助けてください！\n私がへんたいふしんしゃさんに\nなっちゃったみたいなんです…！\nどういう意味かは私もわかりません", "2030/01/01 14:59:59", 6.375, 4, 201, "2026/03/31 12:00:00", "キョウカ", 0.0, -285.0, 6, 61, 10215, 1021502);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (136902, "ましゃか、グレイス姉しゃまたちが\nへんたいふしんしゃさんだなんて…\n騎士しゃん。あたちたちも協力ちて\n二人の破滅エンドを回避ちましょう", "2030/01/01 14:59:59", 6.173, 1, 301, "2026/03/31 12:00:00", "ルルィ", 0.0, -285.0, 6, 61, 10215, 1021503);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (139202, "違う世界に来ちゃうし、\n驚きの連続だけど…\nわたしも精いっぱい頑張ります！\nアストルムのみんなと一緒に！", "2030/01/01 14:59:59", 4.202, 2, 101, "2026/04/30 12:00:00", "ミホ", 0.0, -285.0, 6, 61, 10216, 1021601);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (139302, "想定外の事象が発生したな…だが\nいかなる苦境も切り抜けてみせる\nいつもの自分とは違う姿になっても\nわたしはわたし、西住流だ", "2030/01/01 14:59:59", 2.842, 1, 201, "2026/04/30 12:00:00", "マホ", 0.0, -285.0, 6, 61, 10216, 1021602);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (139402, "何でこんなことになっているのか\n全然わからないけど、迷ってる暇は\nないわ。黒森峰の次期隊長として、\n前進あるのみ！　これも戦車道よ！", "2030/01/01 14:59:59", 4.598, 1, 301, "2026/04/30 12:00:00", "エリカ", 0.0, -285.0, 4, 61, 10216, 1021603);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (125802, "わたくしたちの悲願は、ロストさせ\nてしまった方々をお助けすること…\nそのためなら、どのような辛苦にも\n耐え抜いてみせます…！", "2030/01/01 14:59:59", 6.533, 3, 101, "2026/05/31 12:00:00", "リリ", 0.0, -285.0, 4, 61, 10217, 1021701);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (126102, "みんなも。せーぎも。\nクリアも。パパ、も。\nぜったい、たすける。\nみててね。お兄。", "2030/01/01 14:59:59", 5.0, 3, 301, "2026/05/31 12:00:00", "プレシア", 0.0, -285.0, 3, 61, 10217, 1021702);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (126002, "癒しの力を使うこと…\nもう、ためらいません！\nモネちゃんやお兄さん…\nみんなに許してもらうためにも！", "2030/01/01 14:59:59", 5.214, 4, 201, "2026/05/31 12:00:00", "クリア", 0.0, -285.0, 3, 61, 10217, 1021703);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (139501, "ヴァルキュリア─皆様を助けたい\nという願いを、力にできるのなら…\nわたくしたちは、きっと誰にも\n負けません！　一意専心です…！", "2030/01/01 14:59:59", 8.781, 3, 102, "2026/05/31 12:00:00", "リリ", 0.0, -285.0, 1, 61, 10217, 1021704);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (139601, "このヴァルキュリアって職業、\nまるで天使みたいな格好ですよね\nうーん…『聖女』ちゃんって\n呼ばれるよりは、マシかな？", "2030/01/01 14:59:59", 6.529, 1, 202, "2026/05/31 12:00:00", "クリア", 0.0, -285.0, 2, 61, 10217, 1021705);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (139701, "ばるきり。もーど。\nはね。まっしろ。\nはっぴーちゃんと。おなじ。\nいいかんじ。", "2030/01/01 14:59:59", 3.195, 2, 302, "2026/05/31 12:00:00", "プレシア", 0.0, -285.0, 3, 61, 10217, 1021706);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (139902, "ダーリンと一緒に南の島で\nリゾート開発なんて夢みたい♪\nああ…幸せ、最高の夏だわ…\n触れたら爆発さえしなければ～…っ", "2030/01/01 14:59:59", 12.43, 3, 101, "2026/06/30 12:00:00", "ルイズマリー", 0.0, -285.0, 2, 61, 10218, 1021801);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (140001, "青い空、白い雲…無人島リゾートで\n大儲けですわ～♪　こらこらそこ、\nイチャついてるんじゃないですのよ\n触れたらドカンですわよ、ドカン！", "2030/01/01 14:59:59", 6.35, 3, 201, "2026/06/30 12:00:00", "クレジッタ", 0.0, -285.0, 2, 61, 10218, 1021802);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (140102, "みんなはかわいいぼくを見られて、\nぼくはみんなからラヴをもらう♡\n最高のウィンウィンだよね、これ♡\nで、最後はお兄さんをドレーに…♡", "2030/01/01 14:59:59", 10.23, 5, 101, "2026/07/31 12:00:00", "フブキ", 0.0, -285.0, 1, 61, 10219, 1021901);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (140201, "けんぞくとたくさん遊ぶためにも、\nみんなからラヴをもらわなくちゃ♪\nバズっちゃおー作戦、\n一緒に考えてね！　けんぞくぅ♪", "2030/01/01 14:59:59", 5.584, 2, 201, "2026/07/31 12:00:00", "ヴァンピィ", 0.0, -285.0, 1, 61, 10219, 1021902);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (126401, "あっちもこっちも、\nエマージェンシーですっ！\nみんなのピンチを助けるために\n行きましょうっ、ナイトさんっ！", "2030/01/01 14:59:59", 2.8, 3, 201, "2026/08/31 12:00:00", "クローチェ", 0.0, -285.0, 6, 61, 10220, 1022001);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (127802, "みんながあたしを許してくれても…\nあたしは、あたしを許せない\nそれでも…この世界が危ないなら\n迷ってなんか、いられない", "2030/01/01 14:59:59", 8.9, 3, 101, "2026/08/31 12:00:00", "ヴルム", 0.0, -285.0, 4, 61, 10220, 1022002);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (140602, "クローチェ、サブマリンモードっ\n換装完了ですっ♪\nどんな荒波も、ナイトさんとなら\n越えちゃいますからっ！", "2030/01/01 14:59:59", 4.49, 1, 202, "2026/08/31 12:00:00", "クローチェ", 0.0, -285.0, 2, 61, 10220, 1022003);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (140501, "偽物でも、創り物でもいい\nあたしの中にある気持ちは、\nあたしの本物だから\n今度こそ、この力で守ってみせる", "2030/01/01 14:59:59", 9.42, 3, 102, "2026/08/31 12:00:00", "ヴルム", 0.0, -285.0, 1, 61, 10220, 1022004);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (140402, "世界と向き合うなんてこと…\n私には、わからない\nそれでも、受けた借りは\nちゃんと返さないとね", "2030/01/01 14:59:59", 7.0, 1, 301, "2026/08/31 12:00:00", "リーザ", 0.0, -285.0, 4, 61, 10220, 1022005);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (190801, "ミッションをクリアすると、\n報酬がもらえますよ！\n頑張ってください", "2030/01/01 14:59:59", 3.414, 2, 1, "2026/04/10 12:00:00", "カリン", 0.0, -416.5, 1, 62, 2, 2000001);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (190801, "ミッションをクリアして、\n報酬をゲットしましょう！", "2030/01/01 14:59:59", 3.099, 2, 2, "2026/04/10 12:00:00", "カリン", 0.0, -416.5, 1, 62, 2, 2000002);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (190801, "受け取ることができる\n報酬があるようです\n確認してみてください", "2030/01/01 14:59:59", 2.801, 2, 3, "2026/04/10 12:00:00", "カリン", 0.0, -416.5, 1, 63, 2, 2000003);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (190801, "報酬がもらえますよ！\nチェックしてみてください", "2030/01/01 14:59:59", 0.0, 2, 4, "2026/04/10 12:00:00", "カリン", 0.0, -416.5, 2, 63, 2, 2000004);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (190801, "ギルド管理協会です！\nイベント報酬券をお持ちでしたら、様々なアイテムと交換できますよ", "2030/01/01 14:59:59", 2.12, 1, 5, "2026/04/10 12:00:00", "カリン", 0.0, -363.0, 2, 64, 2, 2000005);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (190801, "お疲れさまです！\nこちらでイベント報酬券とアイテムを交換することができますよ", "2030/01/01 14:59:59", 1.68, 2, 6, "2026/04/10 12:00:00", "カリン", 0.0, -363.0, 1, 64, 2, 2000006);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (190801, "いつもありがとうございます！\n報酬交換ですか？\nでは、イベント報酬券とお引き換えいたしますね", "2030/01/01 14:59:59", 2.33, 1, 7, "2026/04/10 12:00:00", "カリン", 0.0, -363.0, 2, 64, 2, 2000007);
